function longestRidge(elev: number[]): number {
  const n = elev.length;
  let best = 0;
  for (let s = 0; s < n; s++) {
    let j = s;
    while (j + 1 < n && elev[j + 1] > elev[j]) j++;
    if (j === s) continue;
    const top = j;
    while (j + 1 < n && elev[j + 1] < elev[j]) j++;
    if (j > top) best = Math.max(best, j - s + 1);
  }
  return best;
}

