function longestRidge(elev: number[]): number {
  let best = 0, up = 0, down = 0;
  for (let i = 1; i < elev.length; i++) {
    const prev = elev[i - 1], cur = elev[i];
    if (cur === prev || (down > 0 && cur > prev)) up = down = 0;
    if (cur > prev) up++;
    else if (cur < prev) down++;
    if (up > 0 && down > 0) best = Math.max(best, up + down + 1);
  }
  return best;
}

